@triton.jit
def _scatter_t_kernel(
    acc_ptr,
    idx_ptr,
    src_ptr,
    cnt_ptr,
    K,
    T,
    sLx,
    sKx,
    sTx,
    sLa,
    sCa,
    REDUCE: tl.constexpr,
    ADD_CNT: tl.constexpr,
    BJ: tl.constexpr,
    BT: tl.constexpr,
):
    label_index = tl.program_id(0)
    pid_j = tl.program_id(1)
    pid_t = tl.program_id(2)
    js = pid_j * BJ + tl.arange(0, BJ)
    ts = pid_t * BT + tl.arange(0, BT)
    jm = js < K
    tm = ts < T
    idx = tl.load(idx_ptr + js, mask=jm, other=0).to(tl.int64)
    ln = label_index.to(tl.int64)
    soff = ln * sLx + js.to(tl.int64)[:, None] * sKx + ts.to(tl.int64)[None, :] * sTx
    mask = jm[:, None] & tm[None, :]
    doff = ln * sLa + idx[:, None] * sCa + ts.to(tl.int64)[None, :]
    if REDUCE == 0:
        v = tl.load(src_ptr + soff, mask=mask, other=1.0).to(tl.float32)
        v = tl.where(mask, v, 1.0)
        doff = tl.where(mask, doff, 0)
        stop = tl.where(mask, 0, 1).to(tl.int1)
        done = tl.sum(stop.to(tl.int32)) == BJ * BT
        while done == 0:
            cur = tl.load(acc_ptr + doff, mask=mask, other=0.0)
            new = tl.where(stop, cur, cur * v)
            is_nan = (new != new) & (stop == 0)
            new = tl.where(is_nan, v, new)
            cas = tl.atomic_cas(acc_ptr + doff, cur, new, sem="relaxed")
            stop = stop | ((cur == cas) | is_nan)
            done = tl.sum(stop.to(tl.int32)) == BJ * BT
