@triton.jit
def _scan_kernel(
    out_ptr,
    self_ptr,
    idx_ptr,
    src_ptr,
    C,
    K,
    T,
    sLo,
    sCo,
    sTo,
    sLs,
    sCs,
    sTs,
    sLx,
    sKx,
    sTx,
    REDUCE: tl.constexpr,
    INC_SELF: tl.constexpr,
    BT: tl.constexpr,
    BJ: tl.constexpr,
):
    r = tl.program_id(0)
    pid_t = tl.program_id(1)
    ts = pid_t * BT + tl.arange(0, BT)
    tm = ts < T
    label_index = r // C
    ii = r - label_index * C
    ln = label_index.to(tl.int64)
    i64 = ii.to(tl.int64)
    s_off = ln * sLs + i64 * sCs + ts.to(tl.int64) * sTs
    sval = tl.load(self_ptr + s_off, mask=tm, other=0.0).to(tl.float32)
    if INC_SELF:
        acc = sval
    else:
        if REDUCE == 0:
            acc = tl.full((BT,), 1.0, dtype=tl.float32)
        elif REDUCE == 1:
            acc = tl.full((BT,), 0.0, dtype=tl.float32)
        elif REDUCE == 2:
            acc = tl.full((BT,), float("-inf"), dtype=tl.float32)
        else:
            acc = tl.full((BT,), float("inf"), dtype=tl.float32)
    hits = tl.full((), 0, dtype=tl.int32)
    for j0 in range(0, K, BJ):
        js = j0 + tl.arange(0, BJ)
        jm = js < K
        idx = tl.load(idx_ptr + js, mask=jm, other=-1).to(tl.int64)
        match = jm & (idx == i64)
        x_off = (
            ln * sLx + js.to(tl.int64)[:, None] * sKx + ts.to(tl.int64)[None, :] * sTx
        )
        vm = match[:, None] & tm[None, :]
        if REDUCE == 0:
            v = tl.load(src_ptr + x_off, mask=vm, other=1.0).to(tl.float32)
            acc = acc * tl.reduce(v, 0, _mul_combine)
        elif REDUCE == 1:
            v = tl.load(src_ptr + x_off, mask=vm, other=0.0).to(tl.float32)
            acc = acc + tl.sum(v, axis=0)
        elif REDUCE == 2:
            v = tl.load(src_ptr + x_off, mask=vm, other=float("-inf")).to(tl.float32)
            acc = tl.maximum(acc, tl.max(v, axis=0))
        else:
            v = tl.load(src_ptr + x_off, mask=vm, other=float("inf")).to(tl.float32)
            acc = tl.minimum(acc, tl.min(v, axis=0))
        hits = hits + tl.sum(match.to(tl.int32), axis=0)
    if REDUCE == 1:
        if INC_SELF:
            res = acc / (hits.to(tl.float32) + 1.0)
        else:
            res = tl.where(hits > 0, acc / tl.maximum(hits.to(tl.float32), 1.0), sval)
    else:
        if INC_SELF:
            res = acc
        else:
            res = tl.where(hits > 0, acc, sval)
    o_off = ln * sLo + i64 * sCo + ts.to(tl.int64) * sTo
    tl.store(out_ptr + o_off, res.to(out_ptr.dtype.element_ty), mask=tm)


