# counting-sort + single-writer gather (default path)
#
#   1) histogram  cnt[i] = #{j : index[j] == i}
#   2) offsets    exclusive prefix sum, also copies starts into a cursor
#   3) jsort      scatter each j into its column's sorted slot (atomic on cursor)
#   4) gather     one program per output tile folds that column's contiguous
#                 sorted j-run, reading self once and writing out exactly once
# --------------------------------------------------------------------------


@triton.jit
def _hist_kernel(cnt_ptr, idx_ptr, C, K, BC: tl.constexpr, BK: tl.constexpr):
    pid = tl.program_id(0)
    cols = pid * BC + tl.arange(0, BC)
    cmask = cols < C
    c64 = cols.to(tl.int64)[:, None]
    acc = tl.zeros((BC,), dtype=tl.int32)
    for j0 in range(0, K, BK):
        js = j0 + tl.arange(0, BK)
        jm = js < K
        idx = tl.load(idx_ptr + js, mask=jm, other=-1).to(tl.int64)
        hit = (idx[None, :] == c64) & jm[None, :]
        acc += tl.sum(hit.to(tl.int32), axis=1)
    tl.store(cnt_ptr + cols, acc, mask=cmask)


@triton.jit
def _offsets_kernel(off_ptr, cur_ptr, C, BLK: tl.constexpr):
    running = tl.zeros((), dtype=tl.int32)
    for c0 in range(0, C, BLK):
        cols = c0 + tl.arange(0, BLK)
        m = cols < C
        cnt = tl.load(cur_ptr + cols, mask=m, other=0)
        starts = tl.cumsum(cnt, axis=0) - cnt + running
        tl.store(off_ptr + cols, starts, mask=m)
        tl.store(cur_ptr + cols, starts, mask=m)
        running = running + tl.sum(cnt, axis=0)
    tl.store(off_ptr + C, running)


@triton.jit
def _jsort_kernel(sorted_ptr, cur_ptr, idx_ptr, C, K, BJ: tl.constexpr):
    js = tl.program_id(0) * BJ + tl.arange(0, BJ)
    m = js < K
    idx = tl.load(idx_ptr + js, mask=m, other=0).to(tl.int64)
    m = m & (idx >= 0) & (idx < C)
    pos = tl.atomic_add(cur_ptr + idx, 1, mask=m, sem="relaxed")
    tl.store(sorted_ptr + pos, js, mask=m)


