@triton.jit
def _gather_col_kernel(
    out_ptr,
    self_ptr,
    src_ptr,
    sorted_ptr,
    off_ptr,
    C,
    sLo,
    sCo,
    sLs,
    sCs,
    sLx,
    sKx,
    dt_id,
    REDUCE: tl.constexpr,
    INC_SELF: tl.constexpr,
    BC: tl.constexpr,
):
    ln = tl.program_id(0).to(tl.int64)
    cols = tl.program_id(1) * BC + tl.arange(0, BC)
    cm = cols < C
    c64 = cols.to(tl.int64)
    sval = tl.load(self_ptr + ln * sLs + c64 * sCs, mask=cm, other=0.0).to(tl.float32)
    r0 = tl.load(off_ptr + cols, mask=cm, other=0)
    r1 = tl.load(off_ptr + cols + 1, mask=cm, other=0)
    n = r1 - r0
    if INC_SELF:
        acc = sval
    else:
        if REDUCE == 0:
            acc = tl.full((BC,), 1.0, dtype=tl.float32)
        elif REDUCE == 1:
            acc = tl.full((BC,), 0.0, dtype=tl.float32)
        elif REDUCE == 2:
            acc = tl.full((BC,), float("-inf"), dtype=tl.float32)
        else:
            acc = tl.full((BC,), float("inf"), dtype=tl.float32)
    mx = tl.max(n, axis=0)
    for r in range(0, mx):
        rm = r < n
        j = tl.load(sorted_ptr + r0 + r, mask=rm, other=0).to(tl.int64)
        x_off = ln * sLx + j * sKx
        if REDUCE == 0:
            v = tl.load(src_ptr + x_off, mask=rm, other=1.0).to(tl.float32)
            acc = acc * v
        elif REDUCE == 1:
            v = tl.load(src_ptr + x_off, mask=rm, other=0.0).to(tl.float32)
            acc = acc + v
        elif REDUCE == 2:
            v = tl.load(src_ptr + x_off, mask=rm, other=float("-inf")).to(tl.float32)
            acc = tl.maximum(acc, v)
        else:
            v = tl.load(src_ptr + x_off, mask=rm, other=float("inf")).to(tl.float32)
            acc = tl.minimum(acc, v)
    if REDUCE == 1:
        if INC_SELF:
            res = acc / (n.to(tl.float32) + 1.0)
        else:
            res = tl.where(n > 0, acc / tl.maximum(n.to(tl.float32), 1.0), sval)
    else:
        if INC_SELF:
            res = acc
        else:
            res = tl.where(n > 0, acc, sval)
    tl.store(
        out_ptr + ln * sLo + c64 * sCo,
        res.to(out_ptr.dtype.element_ty),
        mask=cm,
    )


